insert into public.species (scientific_name, common_names, description, light, watering, moisture_category, origin, checked_against)
values
  ('Adiantum raddianum', '{"Maidenhair fern","Delta maidenhair"}', 'A delicate fern with fine, fan-shaped leaflets on wiry black stems. It sulks if the soil dries out even once, so it needs close attention.', 'medium', 'Keep the soil evenly moist and never let it dry out.', 'moist', 'curated', 'GBIF'),
